import{z as i,x as p,o as t,c,q as r,j as E,D as e,d as l,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"数据并行的模式","description":"","frontmatter":{"title":"数据并行的模式","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-data-parallel-patterns.md","filePath":"cs/par-data-parallel-patterns.md","lastUpdated":1791413859000}'),B={name:"cs/par-data-parallel-patterns.md"};function A(d,a,m,h,_,f){const s=p("Mermaid");return t(),c("div",null,[a[2]||(a[2]=r('<h1 id="数据并行的模式" tabindex="-1">数据并行的模式 <a class="header-anchor" href="#数据并行的模式" aria-label="Permalink to &quot;数据并行的模式&quot;">​</a></h1><div class="epigraph"><p>数据并行把「这些元素互不干扰」写进数据的形状：形状对了，锁就没有存在的理由。</p><footer>—— 据 Blelloch, Vector Models for Data-Parallel Computing, 1990；Iverson, Notation as a Tool of Thought, CACM 1979 整理</footer></div><p><a href="/cs/par-openmp-mpi">上一课</a>给了两套编程直觉，但没回答「什么时候并行是安全的」。缺口是模式：如果独立性被写进数据的形状——每个元素一份独立计算——那么锁、栅栏、调度都从程序文本里消失。数据并行不是某个 API 的别名，而是比 API 更稳的一层抽象：同一份模式组合，可以从线程循环一路换到 <a href="/cs/gpu-simt">GPU SIMT 与 warp</a> 的上万线程，上层代码不动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基本模式四个。map 对每个元素施加同一个纯操作；reduce 用结合运算把集合折成一个值；scan 算前缀——<a href="/cs/pram-prefix-sum">PRAM 与前缀和</a>的主角，紧凑、过滤、分配下标的公共子程序；gather/scatter 按下标集合搬运。各自的坑：reduce 改变结合次序，浮点和与串行不同；scan 需要的只是结合律，运算不可交换也行；scatter 有写冲突——两个元素落进同一格，硬件不会替你合并，结果取决于谁后写。错法：把带跨迭代依赖的循环（<code>a[i]=f(a[i-1])</code>）当 map 打并行——依赖在迭代之间，形状根本不成立，开再多线程也是串行链。</p><p><span class="marginnote">数字实例：scan（前缀和）输出的是「从头到我这的累加值」：输入 \\([1,2,3,4]\\)、运算取加法，输出 \\([1,3,6,10]\\)。过滤正是用它算新下标——每个幸存元素一查表就知道自己该搬去第几格，不用任何锁或临界区。</span></p><p><span class="marginnote">常见误区：把 <code>a[i]=f(a[i-1])</code> 这样的循环当 map 打并行。第 \\(i\\) 次迭代要等第 \\(i-1\\) 次的结果，是一条串行依赖链，开一万个线程也只会排队。判断标准不是「循环体短不短」，而是「元素 \\(i\\) 需不需要元素 \\(i-1\\) 的结果」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是「先形状，后实现」：把内核拆成模式组合，再挑运行时。例：按谓词过滤 = map 出 0/1 标志 + 排他 scan 算新下标 + scatter 搬元素——三步全是已知模式，work/span 立刻可写，实现从 OpenMP 循环到 GPU 内核都能承接。融合（fusion）把相邻 map 串成一遍过，省掉中间数组的整轮读写：\\(k\\) 个模式各一遍内存，融成一遍，算术强度从 \\(O(1)\\) 提到 \\(O(k)\\)——这一步是后面 roofline 课的伏笔。形状的规则性还决定实现选择：规则的 map/scan 吃得到 SIMD 与 SIMT；不规则的 scatter 在向量机上退化成逐元素访存，红利消失。</p>',9)),(t(),E(o,null,{default:e(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E6%95%B0%E7%BB%84%22%5D%20--%3E%20M%5B%22map%EF%BC%9A%E8%B0%93%E8%AF%8D%E5%BE%97%200%2F1%22%5D%0A%20%20M%20--%3E%20S%5B%22%E6%8E%92%E4%BB%96%20scan%20%E5%BE%97%E7%9B%AE%E6%A0%87%E4%B8%8B%E6%A0%87%22%5D%0A%20%20S%20--%3E%20G%5B%22scatter%20%E6%90%AC%E5%85%83%E7%B4%A0%22%5D%0A%20%20G%20--%3E%20OUT%5B%22%E7%B4%A7%E5%87%91%E5%90%8E%E7%9A%84%E6%95%B0%E7%BB%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模式可组合的机制在账本上：map 的 \\(W=n,S=1\\)、scan 的 \\(W=O(n),S=O(\\log n)\\) 已知，串接的组合界直接相加，运行时不需要理解应用语义——这正是<a href="/cs/par-task-parallel">任务并行</a>一课的工作窃取也能免费承接静态形状的原因。无锁的机制在内存模型上：元素之间不共享写，程序天然 DRF——<a href="/cs/language-memory-model">语言内存模型与 data race</a> 的结论是 DRF 程序可以按顺序一致交错理解，弱一致硬件不再需要你操心。scatter 的冲突是语义选择而非实现细节：原子 RMW 拿到正确但不确定的次序，scan 分桶拿到确定但多一遍的代价——先问结果要不要可复现，再选机制。词法分析、括号匹配这类「看似天生串行」的问题，也靠 scan 变成模式组合，而不是靠手写锁。</p><p><span class="marginnote">同一形状红利在数据库里也兑现一次：<a href="/cs/vectorized-execution">向量化执行</a>把算子从一行一次改成一批一次——与 GPU 把一次一元素改成 warp 一批，是同一个模式直觉。</span></p><p>方法一节那张图画的是「过滤流水线怎么拼」；scatter 的写冲突具体有哪两条出路、各自代价是什么，是另一个问题。</p>',4)),(t(),E(o,null,{default:e(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SC%5B%22scatter%3A%20%E5%A4%9A%E5%85%83%E7%B4%A0%E5%86%99%E5%90%8C%E4%B8%80%E6%A0%BC%22%5D%20--%3E%20Q%7B%22%E7%BB%93%E6%9E%9C%E8%A6%81%E4%B8%8D%E8%A6%81%E5%8F%AF%E5%A4%8D%E7%8E%B0%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%A6%81%22%7C%20BK%5B%22scan%20%E5%88%86%E6%A1%B6%20%E6%8E%92%E5%A5%BD%E5%90%8E%E5%BD%92%E5%B9%B6%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%A6%81%22%7C%20AT%5B%22%E5%8E%9F%E5%AD%90%20RMW%20%E5%B0%B1%E5%9C%B0%E5%90%88%E5%B9%B6%22%5D%0A%20%20BK%20--%3E%20C1%5B%22%E7%BB%93%E6%9E%9C%E7%A1%AE%E5%AE%9A%20%E5%A4%9A%E4%BB%98%E4%B8%80%E9%81%8D%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20AT%20--%3E%20C2%5B%22%E5%AE%9E%E7%8E%B0%E4%BE%BF%E5%AE%9C%20%E5%90%88%E5%B9%B6%E6%AC%A1%E5%BA%8F%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写任务并行——不规则、运行时才现身的并行是下一课的主题；也不写分布式洗牌版的 MapReduce：那是无共享机器之间的另一套账，上一课的 MPI 直觉已够定位它。scan 的推导不再重复，只当已知原语调用。模式清单也不求完备：zip、split、join 都是同一思想的变体，遇到再认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>map/reduce/scan/gather-scatter 是数据并行的基本模式，独立性写在形状里。</li><li>reduce 次序变结果变；scan 只要结合律；scatter 的写冲突要语义决策。</li><li>融合把强度从 \\(O(1)\\) 提到 \\(O(k)\\)；规则形状才吃得到 SIMD 与 SIMT。</li><li>模式先行、实现后选：同一组合可跨线程、向量、GPU 承接。</li><li>出处：Blelloch, 1990；Iverson, CACM 1979。</li></ul><p><span class="marginnote">术语翻译：DRF（data-race-free，无数据竞争）指任何两个同时发生的访存至少有一个是读——不存在两个线程同一时刻写同一格。这类程序可以按「简单顺序执行」理解，在弱内存序硬件上也不会出意外，这正是「形状写对了、锁就不需要了」的底气所在。</span></p>',5))])}const T=i(B,[["render",A]]);export{D as __pageData,T as default};
